import { Component, OnInit } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { MisCompras } from 'src/app/models/mis-compras';

@Component({
  selector: 'app-ejercicio38',
  templateUrl: './ejercicio38.component.html',
  styleUrls: ['./ejercicio38.component.css']
})
export class Ejercicio38Component implements OnInit{

  clienteConMasPedidos: string = '';
  totalProductos: number = 0;

  constructor(public misComprasService: MisComprasService){}

  ngOnInit(): void {
    this.cargarDatos();
  }

  cargarDatos(): void{

    this.misComprasService.obtenerCompras().subscribe(compras => {
      const clienteMap = new Map<string, { totalPedidos: number, totalProductos: number }>();

      compras.forEach(compra => {
        if (!clienteMap.has(compra.emailUsuario)) {
          clienteMap.set(compra.emailUsuario, { totalPedidos: 1, totalProductos: 0 });
        } else {
          clienteMap.get(compra.emailUsuario)!.totalPedidos++;
        }

        compra.productos.forEach(producto => {
          clienteMap.get(compra.emailUsuario)!.totalProductos += producto.cantidad;
        });
      });

      let maxPedidos = 0;
      let clienteMax = '';

      clienteMap.forEach((value, key) => {
        if (value.totalPedidos > maxPedidos) {
          maxPedidos = value.totalPedidos;
          clienteMax = key;
          this.totalProductos = value.totalProductos;
        }
      });

      this.clienteConMasPedidos = clienteMax;
    });

  }

}
<h2>Cliente con más pedidos</h2>
<p>Cliente: {{ clienteConMasPedidos }}</p>
<p>Total de productos del cliente con más pedidos: {{ totalProductos }}</p>
